func etEnd(b []byte) int32 {
	// A golden's end: its length less one final newline (see jsontest).
	var n int32 = port.BlobLen(b)
	if (n > 0) && (port.BlobU8(b, n-1) == 10) {
		return n - 1
	}
	return n
}

